package co.fcv.citas.config; import java.util.List; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.CorsConfiguration; import org.springframework.web.cors.CorsConfigurationSource; import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
@Configuration @EnableWebSecurity public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean org.springframework.security.core.userdetails.UserDetailsService userDetailsService(){return username->{throw new org.springframework.security.core.userdetails.UsernameNotFoundException("No se usa autenticación HTTP básica");};} @Bean CorsConfigurationSource corsConfigurationSource(org.springframework.core.env.Environment env){var c=new CorsConfiguration();c.setAllowedOrigins(List.of(env.getProperty("app.frontend-origin","http://localhost:4200")));c.setAllowedMethods(List.of("POST","GET","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} @Bean SecurityFilterChain security(HttpSecurity http,co.fcv.citas.adapters.in.security.JwtAuthFilter jwtFilter,co.fcv.citas.adapters.in.security.IntegrationTokenFilter integrationFilter)throws Exception{return http.csrf(c->c.disable()).cors(c->{}).addFilterBefore(jwtFilter,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).addFilterBefore(integrationFilter,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/error").permitAll().requestMatchers("/api/v1/integrations/**").hasAuthority(co.fcv.citas.adapters.in.security.IntegrationTokenFilter.ROLE).requestMatchers("/api/v1/admin/**").hasRole("ADMIN").anyRequest().authenticated()).build();} }
